import { Effect, Semaphore } from "effect"
import { identity } from "effect/Function"
import { catalogConcurrency, catalogOrigin } from "./Config.js"

export interface Product {
  readonly sku: string
  readonly title: string
}

export interface Stock {
  readonly available: number
}

export const withRequestConcurrency = catalogConcurrency === "unbounded"
  ? identity
  : Semaphore.makeUnsafe(catalogConcurrency).withPermits(1)

export const fetchProduct = (sku: string) =>
  Effect.tryPromise({
    try: async () => {
      const response = await fetch(`${catalogOrigin}/products/${encodeURIComponent(sku)}`)
      if (!response.ok) throw new Error(`Product request failed: ${response.status}`)
      return (await response.json()) as Product
    },
    catch: (cause) => new Error("Unable to load product", { cause })
  }).pipe(withRequestConcurrency)

export const fetchStock = (sku: string) =>
  Effect.tryPromise({
    try: async () => {
      const response = await fetch(`${catalogOrigin}/stock/${encodeURIComponent(sku)}`)
      if (!response.ok) throw new Error(`Stock request failed: ${response.status}`)
      return (await response.json()) as Stock
    },
    catch: (cause) => new Error("Unable to load stock", { cause })
  }).pipe(withRequestConcurrency)

export const loadProductCard = (sku: string) =>
  Effect.all({ product: fetchProduct(sku), stock: fetchStock(sku) }, {
    concurrency: "unbounded"
  })
